    'landing.action.emergency.rental.description': 'Đến 12 tháng tiền thuê, tiện ích và phí chậm trễ nếu đủ tiêu chuẩn',
    'landing.action.emergency.code.title': 'Báo Cáo Vi Phạm Mã',
    'landing.action.emergency.code.phone': 'Điện Thoại',
    'landing.action.organize.title': 'Cách Bắt Đầu Tổ Chức',
